var i=`0371-alplermagronen`;var t=`world-0371`;var a=`CH`;var r=`western-europe`;var s=4;var o=52;var l={en:`Älplermagronen`,ua:`Альплермагронен`};var d={en:`A traditional Switzerland dish made with macaroni, potato, yellow onion, gruyère. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Швейцарія. Основні інгредієнти: макарони, картопля, жовта цибуля, грюєр. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Cook the listed ingredients in simmering water for about 12 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 12 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:12,i:[[`macaroni`,360,`g`],[`potato`,420,`g`],[`water`,1200,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,180,`g`],[`unsalted-butter`,60,`g`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:10,i:[[`gruyere`,290,`g`],[`heavy-cream`,270,`ml`]]},{en:`Roast in a preheated 190°C oven for about 16 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 16 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:16,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`apple-sauce`,180,`g`]]}];var u={slug:i,id:t,country:`CH`,region:r,servings:4,minutes:52,title:l,text:d,steps:g};export{a as country,u as default,t as id,o as minutes,r as region,s as servings,i as slug,g as steps,d as text,l as title};